    <script>
        pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.10.377/pdf.worker.min.js';
        
        async function renderAllDocuments() {
            const documents = <?= json_encode($documents ?? []) ?>;
            const renderPromises = Object.entries(documents).map(async ([docType, base64String]) => {
                if (base64String) {
                    await renderPDF(base64String);
                }
            });
            await Promise.all(renderPromises);
        }

        function printDocument() {
            window.print();
        }
        
        window.onload = async function() {
            await renderAllDocuments();
            <?php if(request('pdf') == 1): ?>
                document.querySelector('.print-button').style.display = 'none';
                
                var element = document.body;
                var opt = {
                  margin:       0.2,
                  filename:     '<?php echo isset($dataReport['nosepaaa']) && $dataReport['nosepaaa'] != '' ? $dataReport['nosepaaa'] : 'Dokumen_Medis'; ?>.pdf',
                  image:        { type: 'jpeg', quality: 0.98 },
                  html2canvas:  { scale: 2, useCORS: true },
                  jsPDF:        { unit: 'in', format: 'a3', orientation: 'portrait' }
                };

                html2pdf().set(opt).from(element).save().then(function() {
                    // Tutup tab secara otomatis setelah download ter-trigger
                    setTimeout(function() { window.close(); }, 500);
                });
            <?php endif; ?>
        }
        
        async function renderPDF(base64, docType, isSpecialDoc = false) {
            if (!base64) return;
            const base64Encoded = base64.substring(28);
            const byteCharacters = atob(base64Encoded);
            const byteNumbers = new Array(byteCharacters.length).fill().map((_, i) => byteCharacters.charCodeAt(i));
            const byteArray = new Uint8Array(byteNumbers);
            const blob = new Blob([byteArray], {type: 'application/pdf'});
            const loadingTask = pdfjsLib.getDocument({data: byteArray});
            try {
                const pdfDoc = await loadingTask.promise;

                // Wrapper div for each document
                const container = document.createElement('div');
                container.id = `doc-${docType}`;
                container.className = 'document-container';
                document.body.appendChild(container);

                for (let pageNum = 1; pageNum <= pdfDoc.numPages; pageNum++) {
                    const page = await pdfDoc.getPage(pageNum);
                    const scale = 3;
                    const viewport = page.getViewport({scale: scale});
                    const canvas = document.createElement('canvas');
                    const context = canvas.getContext('2d');
                    canvas.height = viewport.height;
                    canvas.width = viewport.width;

                    const renderContext = {
                        canvasContext: context,
                        viewport: viewport
                    };

                    await page.render(renderContext).promise;

                    // Append to the specific container
                    container.appendChild(canvas);

                    // Ensure a page break for multi-page documents
                    if (pageNum < pdfDoc.numPages) {
                        const pageBreak = document.createElement('div');
                        pageBreak.style.pageBreakAfter = 'always';
                        container.appendChild(pageBreak);
                    }
                    // Hapus elemen kosong
                    if (!container.querySelector('canvas')) {
                        container.remove();
                    }
                }
            } catch (error) {
                console.error('Error rendering PDF: ' + error);
            }
        }
    </script>
