            $isTrueEmergency = false;
            $isFalseEmergency = false;
            
            // Ini adalah mapping dari ats1_ids, ats2_ids, dan ats3_ids milik JS Anda
            $trueEmergencyKeys = [
                'disability1', 'disability2', 'disability3', 'airway1', 'airway2', 'breathing1', 'breathing2', 'breathing3', 'circulation1', 'circulation2', 'circulation3', 'gawat1', 'gawat24', 'gawat25', // ATS 1
                'disability4', 'disability5', 'disability6', 'breathing4', 'breathing5', 'circulation4', 'circulation5', 'circulation20', 'circulation6', 'circulation8', 'circulation7', 'circulation9', 'nyeriberat', 'gawat7', 'gawat4', 'gawat8', 'gawat5', 'gawat6', 'gawat26', 'gawat27', // ATS 2
                'disability7', 'disability8', 'disability9', 'breathing66', 'circulation10', 'circulation11', 'circulation12', 'circulation13', 'circulation14', 'circulation15', 'gawat11', 'gawat14' // ATS 3
            ];

            // Ini adalah mapping dari false_ids milik JS Anda
            $falseEmergencyKeys = [
                'airway3', 'disability10', 'disability11', 'disability12', 'airway4', 'airway5', 'breathing8', 'breathing9', 'breathing10', 'circulation16', 'circulation18', 'circulation19', 'nyeriringan', 'circulation17', 'gawat18', 'gawat30', 'gawat31', 'gawat21', 'gawat22', 'gawat23', 'nyerisedang', 'gawat12', 'gawat13', 'breathing7', 'circulation100', 'gawat29', 'breathing6', 'gawat28'
            ];

            // Cek apakah masuk kategori TRUE EMERGENCY
            foreach($trueEmergencyKeys as $key) {
                if(isset($dataReport['dataTriaseIGD'][$key]) && $dataReport['dataTriaseIGD'][$key] == 'checked') {
                    $isTrueEmergency = true;
                    break; 
                }
            }

            // Jika bukan True Emergency, cek apakah masuk FALSE EMERGENCY
            if(!$isTrueEmergency) {
                foreach($falseEmergencyKeys as $key) {
                    if(isset($dataReport['dataTriaseIGD'][$key]) && $dataReport['dataTriaseIGD'][$key] == 'checked') {
                        $isFalseEmergency = true;
                        break;
                    }
                }
            }
